<?php
declare(strict_types=1);
require_once __DIR__.'/../player-assistant-broker/BoundedRepairService.php';
function repairAssert(bool $v,string $m):void{if(!$v)throw new RuntimeException($m);}
function repairReject(callable $f,string $code):void{try{$f();}catch(BoundedRepairException $e){repairAssert($e->getMessage()===$code,"expected $code got ".$e->getMessage());return;}throw new RuntimeException("accepted $code");}
$root=sys_get_temp_dir().'/pa-repair-'.bin2hex(random_bytes(4)); mkdir($root,0700,true); $journal=$root.'/audit.jsonl'; $account=str_repeat('a',32); $other=str_repeat('b',32); $path=$root.'/alpha.json'; file_put_contents($path,'{"status":"bad"}'); $before=hash_file('sha256',$path); $afterBytes='{"status":"fixed"}'; $after=hash('sha256',$afterBytes); $base=fn(array $extra=[]):array=>array_replace(['approval'=>'REPAIR_APPROVED','mode'=>'repair','repair_id'=>'r1','operator_id'=>'op1','account_id'=>$account,'generation'=>'g1','expected_generation'=>'g1','operations'=>[['resource'=>'cache','record_id'=>'alpha','owner_account_id'=>$account,'generation'=>'g1','path'=>$path,'before_sha256'=>$before,'after_sha256'=>$after,'content_base64'=>base64_encode($afterBytes)] ]],$extra);
$s=new BoundedRepairService($root,$journal,'g1',['cache'=>$account]);
$r=$s->execute($base(),true); repairAssert($r['status']==='dry-run' && file_get_contents($path)==='{"status":"bad"}','dry run mutated'); repairAssert(is_file($journal),'dry run audit missing');
$r=$s->execute($base(),false); repairAssert($r['status']==='applied'&&file_get_contents($path)===$afterBytes,'valid repair failed'); $again=$s->execute(array_replace($base(),['repair_id'=>'r2','operations'=>[array_replace($base()['operations'][0],['before_sha256'=>$after])]]),false); repairAssert($again['status']==='applied','idempotent repair failed');
repairReject(fn()=>$s->execute($base(['repair_id'=>'bad!'])), 'malformed_identity'); repairReject(fn()=>$s->execute($base(['expected_generation'=>'g0'])), 'stale_generation'); repairReject(fn()=>$s->execute($base(['operations'=>[array_replace($base()['operations'][0],['owner_account_id'=>$other])]])), 'ownership_or_shape_rejected'); repairReject(fn()=>$s->execute($base(['operations'=>[array_replace($base()['operations'][0],['path'=>$root.'/../alpha.json'])]])), 'unsafe_path'); repairReject(fn()=>$s->execute($base(['operations'=>[array_replace($base()['operations'][0],['resource'=>'quests','owner_account_id'=>$account])]])), 'ownership_ambiguous'); repairReject(fn()=>$s->execute($base(['operations'=>[array_replace($base()['operations'][0],['content_base64'=>base64_encode(str_repeat('x',1048577))])]])), 'repair_size_limit'); repairReject(fn()=>$s->execute($base(['operations'=>[array_replace($base()['operations'][0],['before_sha256'=>str_repeat('0',64)])]]),false), 'stale_record');
$cancelled=true; repairReject(fn()=>$s->execute(array_replace($base(),['repair_id'=>'cancel2']),false,fn()=>$cancelled), 'repair_cancelled'); repairAssert(file_get_contents($path)===$afterBytes,'cancel mutated');
$second=$root.'/beta.json'; file_put_contents($second,'{\"status\":\"bad\"}'); $secondOp=['resource'=>'cache','record_id'=>'beta','owner_account_id'=>$account,'generation'=>'g1','path'=>$second,'before_sha256'=>hash_file('sha256',$second),'after_sha256'=>$after,'content_base64'=>base64_encode($afterBytes)]; $firstBefore=file_get_contents($path); repairReject(fn()=>$s->execute(array_replace($base(),['repair_id'=>'rollback','operations'=>[$base()['operations'][0],array_replace($secondOp,['before_sha256'=>str_repeat('0',64)])]]),false), 'stale_record'); repairAssert(file_get_contents($path)===$firstBefore && file_get_contents($second)==='{\"status\":\"bad\"}','rollback did not restore all files');
repairReject(fn()=>$s->execute(array_replace($base(),['account_id'=>''])), 'malformed_request'); repairReject(fn()=>$s->execute(array_replace($base(),['operations'=>[array_replace($base()['operations'][0],['owner_account_id'=>$other,'resource'=>'cache'])]])), 'ownership_or_shape_rejected');
$lines=file($journal,FILE_IGNORE_NEW_LINES); repairAssert(count($lines)>=4,'audit entries missing'); echo "Bounded repair tests passed.\n";
